  const stage=$('#stage');stage.classList.toggle('moving',v.st==='road'||v.st==='ret');stage.className='stage st-'+v.st+((v.st==='road'||v.st==='ret')?' moving':'');
  $('#stageTags').innerHTML='<span>'+v.n+'</span><span class="c-'+v.st+'">● '+v.label.toUpperCase()+'</span><span>'+v.loc.toUpperCase()+'</span>';
  runCheck();
