let psx=null;$('#cam').addEventListener('touchstart',e=>{psx=e.touches[0].clientX},{passive:true});$('#cam').addEventListener('touchend',e=>{if(psx===null)return;const dx=e.changedTouches[0].clientX-psx;if(Math.abs(dx)>40){showP(pi+(dx<0?1:-1));userP();}else{const r=$('#cam').getBoundingClientRect();if(e.changedTouches[0].clientX-r.left>r.width*.6){showP(pi+1);userP();}else if(e.changedTouches[0].clientX-r.left<r.width*.4){showP(pi-1);userP();}}psx=null;});
