RUN("s-trust",function(document,__host,__root){

(function(){
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
const buzz=()=>{try{navigator.vibrate&&navigator.vibrate(8)}catch(e){}};
const io=(el,fn,th)=>{if(!('IntersectionObserver' in window))return fn();new IntersectionObserver((es,o)=>{if(es.some(x=>x.isIntersecting)){fn();o.disconnect();}},{threshold:th||.3}).observe(el);};
const count=(b,to,suf,dur)=>{if(RM)return;const t0=performance.now();const f=t=>{const k=Math.min(1,(t-t0)/(dur||1400));b.textContent=Math.round(to*(1-Math.pow(1-k,3)))+(suf||'');if(k<1)requestAnimationFrame(f)};requestAnimationFrame(f);};

/* ===== why ===== */
// dial ticks + arcs
let tk='';for(let m=0;m<60;m++){const a=(m*6-90)*Math.PI/180,r1=m%5?118:112;tk+='<line class="tk'+(m%5?'':' b')+'" x1="'+(130+Math.cos(a)*124)+'" y1="'+(130+Math.sin(a)*124)+'" x2="'+(130+Math.cos(a)*r1)+'" y2="'+(130+Math.sin(a)*r1)+'"/>';}$('#ticks').innerHTML=tk;
const cE=2*Math.PI*100,cA=2*Math.PI*86;$('#arcE').setAttribute('stroke-dasharray',cE);$('#arcE').setAttribute('stroke-dashoffset',cE);$('#arcA').setAttribute('stroke-dasharray',cA);$('#arcA').setAttribute('stroke-dashoffset',cA);
function race(){const lanes=$$('.lane');lanes.forEach(l=>{$('.car',l).style.transition='none';$('.trail',l).style.transition='none';$('.car',l).style.left='4px';$('.trail',l).style.width='0';});
  void document.body.offsetWidth;
  [[lanes[0],28],[lanes[1],32]].forEach(([l,m])=>{const p=m/32;const car=$('.car',l),tr=$('.trail',l);const dur=RM?0:(1.4*m/28);car.style.transition='left '+dur+'s cubic-bezier(.4,0,.2,1)';tr.style.transition='width '+dur+'s cubic-bezier(.4,0,.2,1)';car.style.left='calc('+(p*100)+'% - 30px)';tr.style.width='calc('+(p*100)+'% - 20px)';});}
io($('#resp'),()=>{$('#arcE').style.strokeDashoffset=cE*(1-28/60);$('#arcA').style.strokeDashoffset=cA*(1-32/60);race();},.4);
$('#replay').addEventListener('click',()=>{race();buzz();});
// operator countdown (loops)
let cd=8;const cdF=$('#cdF');
function cdTick(){cd--;if(cd<0)cd=8;$('#cdN').textContent=cd;cdF.style.strokeDashoffset=289*(1-cd/8);
  const st=$('#opSt');if(cd===0){st.textContent='● Operatör bağlandı';st.classList.add('live');}else{st.textContent='Ortalama cevap · '+cd+'s';st.classList.remove('live');}}
if(!RM)setInterval(cdTick,1000);
// months grid
const mo=$('#months');for(let k=0;k<24;k++){const i=document.createElement('i');if(k===23)i.className='end';mo.appendChild(i);}
io($('#war'),()=>{$$('#months i').forEach((m,k)=>setTimeout(()=>m.classList.add('on'),RM?0:k*60));const n=$('#mN');if(!RM){let k=0;const t=setInterval(()=>{n.textContent=++k;if(k>=24)clearInterval(t);},60);}});
// year
$('#yr').innerHTML=[...Array(12)].map((_,k)=>'<i style="--k:'+k+'"></i>').join('');
// satisfaction + stats
io($('.sat'),()=>{$('#satBar').style.width='98%';count($('#satN'),98,'%');});
io($('#stats'),()=>{$$('#stats b[data-to]').forEach(b=>count(b,+b.dataset.to,b.dataset.suf||''));});
})();

});
