  c.innerHTML='<span class="qm" aria-hidden="true">“</span><div class="top"><div class="who"><span class="av" style="background:'+r.c+'">'+r.n[0]+'</span><div><b>'+r.n+'</b><small>'+r.l+' · Doğrulandı</small></div></div><span class="src">G · Google</span></div><div class="st">★★★★★</div><p class="tx">“'+r.t+'”</p><div class="ft"><span class="metric"><b>'+r.m[0]+'</b>'+r.m[1]+'</span>'+(hasTTS?'<button type="button" class="listen" aria-label="Bu yorumu dinle"><svg><use href="#i-vol"/></svg><span class="eqb"><i></i><i></i><i></i></span>Dinle</button>':'')+'</div>';
  ring.appendChild(c);
